/**
 * registerSW.ts — registers the service worker (generated by vite-plugin-pwa, vite.config.ts) and
 * applies app updates only at a SAFE moment.
 *
 * The service worker caches the whole app so it opens offline. We use the plugin's "prompt" mode:
 * when a new version has downloaded, the old one keeps running until WE tell the new one to take
 * over. No prompt is shown to the user; we just wait for a moment when a reload can't destroy work:
 * the user is on a bottom-nav tab (Inicio, Temas, Exámenes, Perfil, Ajustes). Never during an exam,
 * a study question, or while typing an unlock code — even if the app is put in the background.
 *
 * Two steps are guarded, because several copies of the app may be open (installed app + tab):
 *   1. telling the new service worker to take over (`applyIfSafe`), and
 *   2. reloading THIS page after a new worker took over — possibly triggered by another copy
 *      (`onNeedReload` → `reloadIfSafe`).
 * Open apps also check for updates every hour. Docs: docs/DEPLOY.md → "How updates reach phones".
 */
import { registerSW } from 'virtual:pwa-register'
import { TAB_ROUTES } from '../ui/router'

let pendingUpdate: ((reload?: boolean) => Promise<void>) | null = null
let pendingReload = false

/** True when the current screen is a bottom-nav tab (nothing in progress to lose). */
function onTabScreen(): boolean {
  const path = window.location.hash.replace(/^#/, '') || '/home'
  return (TAB_ROUTES as readonly string[]).includes(path)
}

function applyIfSafe(): void {
  if (pendingUpdate && onTabScreen()) {
    const apply = pendingUpdate
    pendingUpdate = null
    void apply(true)
  }
}

function reloadIfSafe(): void {
  if (pendingReload && onTabScreen()) {
    pendingReload = false
    window.location.reload()
  }
}

/** Registers the service worker (no-op in dev and in browsers without support). */
export function registerServiceWorker(): void {
  if (!('serviceWorker' in navigator) || import.meta.env.DEV) return
  const updateSW = registerSW({
    immediate: true,
    onNeedRefresh() {
      pendingUpdate = updateSW
      applyIfSafe()
    },
    // A new version took control (from this copy or another one): reload when safe, not instantly.
    onNeedReload() {
      pendingReload = true
      reloadIfSafe()
    },
    onRegisteredSW(_url, registration) {
      if (!registration) return
      setInterval(() => void registration.update(), 60 * 60 * 1000)
    },
  })
  window.addEventListener('hashchange', () => {
    applyIfSafe()
    reloadIfSafe()
  })
}
